import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();
        final long MOD = 1000000007;

        if (k != 1 && k != 0) {
            boolean[] visited = new boolean[(int) p];
            for (int i = 0; i < p; i++) {
                visited[i] = true;
            }
            long result = 1;
            for (long start = 1; start < p; start++) {
                if (visited[(int) start]) {
                    long current = start;
                    do {
                        current = (current * k) % p;
                        visited[(int) current] = false;
                    } while (current != start);
                    result = (result * p) % MOD;
                }
            }
            System.out.println(result);
        } else if (k == 1) {
            long total = 1;
            for (long i = 0; i < p; i++) {
                total = (total * p) % MOD;
            }
            System.out.println(total);
        } else {
            long total = 1;
            for (long i = 0; i < p - 1; i++) {
                total = (total * p) % MOD;
            }
            System.out.println(total);
        }
        scanner.close();
    }
}
